import React from 'react';
import { Input, FormItem, Submit } from '@storage-fe/formily-arco';
import { createForm } from '@formily/core';
import { FormProvider, createSchemaField } from '@formily/react';

const SchemaField = createSchemaField({
  components: {
    Input,
    FormItem,
  },
});

const form = createForm();

export default () => (
  <FormProvider form={form}>
    <SchemaField>
      <SchemaField.String name="input" title="input box" required x-decorator="FormItem" x-component="Input" />
      <SchemaField.String
        name="input2"
        title="input box"
        default="123"
        required
        x-decorator="FormItem"
        x-component="Input"
      />
    </SchemaField>
    <Submit
      onSubmit={values =>
        new Promise(resolve => {
          setTimeout(() => {
            console.log(values);
            resolve('');
          }, 2000);
        })
      }
      onSubmitFailed={console.log}
    >
      submit
    </Submit>
  </FormProvider>
);
